export type TenantId = 'slime' | 'ember' | 'ghost' | 'golem';
export type Tenant = { id: TenantId; name: string; icon: string; color: number; price: number; rent: number; description: string };
export type DayResult = { day: number; rent: number; upkeep: number; synergy: number; event: number; eventTitle: string; eventDetail: string; net: number };
export type GameState = { day: number; coins: number; satisfaction: number; rooms: (TenantId|null)[]; history: DayResult[]; over: boolean; outcome: 'win'|'lose'|null; notice: string; log: string[] };
export type GameOutcome = { state: GameState; error: string|null };
export const TENANTS: Record<TenantId,Tenant>;
export const TENANT_IDS: TenantId[];
export const ROOM_COUNT: number;
export const LAST_DAY: number;
export const TARGET_COINS: number;
export function newGame(): GameState;
export function adjacency(rooms:(TenantId|null)[]): [number,number][];
export function synergyDetails(rooms:(TenantId|null)[]): { coins:number; satisfaction:number; messages:string[] };
export function hire(state:GameState,index:number,tenantId:TenantId): GameOutcome;
export function moveOrSwap(state:GameState,a:number,b:number): GameOutcome;
export function nightlyEvent(rooms:(TenantId|null)[],day:number,satisfaction:number): {title:string;detail:string;coins:number;satisfaction:number};
export function advanceDay(state:GameState): GameOutcome;
